actions.script:
const txMap = {};
for (const row of (rawEntries || [])) {
    const txId = row.acctgTransId;
    let tx = txMap[txId];
    if (!tx) {
        tx = {
            acctgTransId: txId,
            transactionDate: row.transactionDate,
            txDescription: row.txDescription || '',
            txVoucherRef: row.txVoucherRef || '',
            txVoucherDate: row.txVoucherDate,
            invoiceId: row.invoiceId,
            paymentId: row.paymentId,
            journalSequenceNum: row.journalSequenceNum,
            entries: []
        };
        txMap[txId] = tx;
    }
    const isDebit = (row.debitCreditFlag === 'D');
    const amt = Number(row.amount) || 0;
    tx.entries.push({
        acctgTransEntrySeqId: row.acctgTransEntrySeqId,
        glAccountId: row.glAccountId,
        accountCode: row.accountCode || row.glAccountId,
        accountName: row.accountName || '',
        debitCreditFlag: row.debitCreditFlag,
        debitAmount: isDebit ? amt : 0,
        creditAmount: !isDebit ? amt : 0
    });
}

const txList = Object.values(txMap);
context.totalTransactions = txList.length;
context.totalEntries = (rawEntries || []).length;

// Sequential numbering if missing in preview
let seq = 1;
for (const tx of txList) {
    if (!tx.journalSequenceNum) tx.journalSequenceNum = seq;
    seq++;
}

// Page distribution
const maxLines = Number(linesPerPage) || 24;
const pages = [];
let currentPage = null;
let pageNum = Number(startPageNumber) || 1;
let runningDebit = 0;
let runningCredit = 0;
let currentLines = 0;

function startNewPage() {
    currentPage = {
        pageNumber: pageNum,
        pageLabel: fiscalYear + ' / ' + pageNum,
        broughtForwardDebit: runningDebit,
        broughtForwardCredit: runningCredit,
        carriedForwardDebit: runningDebit,
        carriedForwardCredit: runningCredit,
        transactions: []
    };
    pages.push(currentPage);
    pageNum++;
    currentLines = 0;
}

if (txList.length > 0) startNewPage();

for (const tx of txList) {
    const txLineCount = 1 + tx.entries.length;
    if (currentLines + txLineCount > maxLines && currentLines > 0) {
        currentPage.carriedForwardDebit = runningDebit;
        currentPage.carriedForwardCredit = runningCredit;
        startNewPage();
    }
    for (const entry of tx.entries) {
        runningDebit += entry.debitAmount;
        runningCredit += entry.creditAmount;
    }
    currentPage.transactions.push(tx);
    currentLines += txLineCount;
}

if (currentPage) {
    currentPage.carriedForwardDebit = runningDebit;
    currentPage.carriedForwardCredit = runningCredit;
}

context.pages = pages;
context.totalDebit = runningDebit;
context.totalCredit = runningCredit;
context.endPageNumber = pageNum - 1;
context.isFinalized = false;

let count = 0;
let currentSeq = 1;
for (const p of (journalData.pages || [])) {
    for (const tx of (p.transactions || [])) {
        ec.entity.find("mantle.ledger.transaction.AcctgTrans")
            .condition("acctgTransId", tx.acctgTransId)
            .one()
            .set("journalSequenceNum", currentSeq)
            .set("fiscalYear", fiscalYear)
            .update();
        currentSeq++;
        count++;
    }
}
context.transactionsLocked = count;

const isSales = (registerType === 'sales');
const isPurchases = (registerType === 'purchases');
const isSummary = (registerType === 'summary');

const validTypes = ['InvoiceSales', 'InvoicePurchase', 'InvoiceReturn', 'InvoiceCreditMemo'];
let q = ec.entity.find("mantle.account.invoice.Invoice");
if (isSales) {
    q = q.condition("fromPartyId", organizationPartyId);
    q = q.condition("invoiceTypeEnumId", "in", validTypes);
} else if (isPurchases) {
    q = q.condition("toPartyId", organizationPartyId);
    q = q.condition("invoiceTypeEnumId", "in", validTypes);
} else {
    // Summary: include both
    const conds = ec.entity.conditionFactory;
    q = q.condition(conds.makeCondition([
        conds.makeCondition("fromPartyId", "equals", organizationPartyId),
        conds.makeCondition("toPartyId", "equals", organizationPartyId)
    ], "or"));
    q = q.condition("invoiceTypeEnumId", "in", validTypes);
}

if (fromDate) q = q.condition("invoiceDate", "greater-equals", fromDate);
if (thruDate) q = q.condition("invoiceDate", "less-equals", thruDate);
if (vatRegisterSeries) q = q.condition("vatRegisterSeries", vatRegisterSeries);

// Exclude drafts
q = q.condition("statusId", "not-equals", "InvoiceInProcess");
q = q.orderBy("invoiceDate,invoiceId");

const invoices = q.list() || [];
const docRows = [];
const rateSummaryMap = {};
let sumTaxable = 0;
let sumTax = 0;
let sumDocTotal = 0;
let sumDeductible = 0;
let sumNonDeductible = 0;
let salesTaxSum = 0;
let purchaseTaxDeductibleSum = 0;
let salesTaxableSum = 0;
let purchaseTaxableSum = 0;

const toNum = (v) => (v == null ? 0 : (typeof v === 'object' && typeof v.toNumber === 'function' ? v.toNumber() : (Number(v) || 0)));
const taxItemTypes = ['ItemVatTax', 'ItemVatTaxTotal', 'ItemSalesTax', 'ItemTax'];
const resolveNatureCode = (raw) => {
    if (!raw) return '';
    if (/^N[1-7](\.[0-9])?$/.test(raw)) return raw;
    const enumRec = ec.entity.find("moqui.basic.Enumeration").condition("enumId", raw).useCache(true).one();
    return enumRec?.enumCode || '';
};
const summarizeInvoiceItems = (inv) => {
    const isSale = (inv.fromPartyId === organizationPartyId);
    const isCreditNote = (inv.invoiceTypeEnumId === 'InvoiceCreditMemo' || inv.invoiceTypeEnumId === 'InvoiceReturn');
    const sign = isCreditNote ? -1 : 1;
    const items = ec.entity.find("mantle.account.invoice.InvoiceItem")
        .condition("invoiceId", inv.invoiceId)
        .orderBy("invoiceItemSeqId")
        .list() || [];

    const goodsItems = [];
    const taxItems = [];
    for (const item of items) {
        const enumRec = ec.entity.find("moqui.basic.Enumeration").condition("enumId", item.itemTypeEnumId).useCache(true).one();
        const isTaxLine = taxItemTypes.includes(item.itemTypeEnumId);
        if (isTaxLine) {
            taxItems.push(item);
        } else {
            goodsItems.push({ item: item, enumRec: enumRec });
        }
    }

    let docTaxable = 0;
    let docTax = 0;
    let docDeductible = 0;
    let docNonDeductible = 0;
    const docRatesMap = {};
    const goodsBySeq = {};

    for (const g of goodsItems) {
        const item = g.item;
        const amt = sign * toNum(item.amount) * (item.quantity != null ? toNum(item.quantity) : 1);
        docTaxable += amt;
        goodsBySeq[item.invoiceItemSeqId] = { amt: amt, item: item, enumRec: g.enumRec };
    }

    const addBucket = (rate, nature, taxableDelta, taxDelta, nonDedDelta) => {
        const rateStr = (Math.round(rate * 100) / 100).toString();
        const key = rateStr + '_' + (nature || '');
        if (!docRatesMap[key]) {
            docRatesMap[key] = { rate: rate, nature: nature || '', taxable: 0, tax: 0, nonDed: 0 };
        }
        docRatesMap[key].taxable += taxableDelta;
        docRatesMap[key].tax += taxDelta;
        docRatesMap[key].nonDed += nonDedDelta;
    };

    if (taxItems.length > 0) {
        let linkedTaxTotal = 0;
        let unlinkedTaxTotal = 0;
        const unlinkedRates = [];
        for (const t of taxItems) {
            const tAmt = sign * toNum(t.amount) * (t.quantity != null ? toNum(t.quantity) : 1);
            const tRate = t.taxPercentage != null ? toNum(t.taxPercentage) : 0;
            const tNature = resolveNatureCode(t.vatNatureEnumId);
            let tNonDed = 0;
            if (!isSale) {
                if (t.nonDeductibleAmount != null) tNonDed = sign * toNum(t.nonDeductibleAmount);
                else if (t.nonDeductiblePercentage != null) tNonDed = tAmt * (toNum(t.nonDeductiblePercentage) / 100);
            }
            docTax += tAmt;
            docNonDeductible += tNonDed;
            docDeductible += (tAmt - tNonDed);

            if (t.parentItemSeqId && goodsBySeq[t.parentItemSeqId]) {
                const parent = goodsBySeq[t.parentItemSeqId];
                parent._matched = true;
                addBucket(tRate, tNature, parent.amt, tAmt, tNonDed);
                linkedTaxTotal += tAmt;
            } else {
                unlinkedTaxTotal += tAmt;
                unlinkedRates.push({ rate: tRate, nature: tNature, tax: tAmt, nonDed: tNonDed });
            }
        }
        // Distribute unmatched goods across unlinked tax buckets
        const unmatchedGoods = Object.values(goodsBySeq).filter(g => !g._matched);
        const unmatchedTaxable = unmatchedGoods.reduce((s, g) => s + g.amt, 0);
        if (unlinkedRates.length === 1) {
            addBucket(unlinkedRates[0].rate, unlinkedRates[0].nature, unmatchedTaxable, unlinkedRates[0].tax, unlinkedRates[0].nonDed);
        } else if (unlinkedRates.length > 1) {
            const totalUnlinkedTax = unlinkedRates.reduce((s, r) => s + r.tax, 0);
            for (const r of unlinkedRates) {
                const share = totalUnlinkedTax !== 0 ? (r.tax / totalUnlinkedTax) : (1 / unlinkedRates.length);
                addBucket(r.rate, r.nature, unmatchedTaxable * share, r.tax, r.nonDed);
            }
        }
    } else {
        // No explicit tax line: group by goods item taxPercentage / statutory VAT nature (N1-N7)
        for (const g of goodsItems) {
            const item = g.item;
            const amt = sign * toNum(item.amount) * (item.quantity != null ? toNum(item.quantity) : 1);
            const nature = resolveNatureCode(item.vatNatureEnumId || g.enumRec?.enumCode);
            const rate = item.taxPercentage != null ? toNum(item.taxPercentage) : 0;
            const calcTax = rate > 0 ? (amt * rate / 100) : 0;
            let nonDed = 0;
            if (!isSale && calcTax !== 0 && item.nonDeductiblePercentage != null) {
                nonDed = calcTax * (toNum(item.nonDeductiblePercentage) / 100);
            }
            docTax += calcTax;
            docNonDeductible += nonDed;
            docDeductible += (calcTax - nonDed);
            addBucket(rate, nature, amt, calcTax, nonDed);
        }
    }

    const rawInvTotal = inv.invoiceTotal != null ? toNum(inv.invoiceTotal) : null;
    return {
        isSale: isSale,
        docTaxable: docTaxable,
        docTax: docTax,
        docDeductible: docDeductible,
        docNonDeductible: docNonDeductible,
        docTotal: rawInvTotal != null ? (sign * Math.abs(rawInvTotal)) : (docTaxable + docTax),
        buckets: Object.values(docRatesMap)
    };
};

// Always compute period settlement totals across both sales & purchases in date range
const condsAll = ec.entity.conditionFactory;
let qAll = ec.entity.find("mantle.account.invoice.Invoice")
    .condition(condsAll.makeCondition([
        condsAll.makeCondition("fromPartyId", "equals", organizationPartyId),
        condsAll.makeCondition("toPartyId", "equals", organizationPartyId)
    ], "or"))
    .condition("invoiceTypeEnumId", "in", validTypes)
    .condition("statusId", "not-equals", "InvoiceInProcess");
if (fromDate) qAll = qAll.condition("invoiceDate", "greater-equals", fromDate);
if (thruDate) qAll = qAll.condition("invoiceDate", "less-equals", thruDate);
const allPeriodInvoices = qAll.list() || [];
for (const pInv of allPeriodInvoices) {
    const pSum = summarizeInvoiceItems(pInv);
    if (pSum.isSale) {
        salesTaxSum += pSum.docTax;
        salesTaxableSum += pSum.docTaxable;
    } else {
        purchaseTaxDeductibleSum += pSum.docDeductible;
        purchaseTaxableSum += pSum.docTaxable;
    }
}

let protocolSeq = 1;

for (const inv of invoices) {
    const isInvoiceSale = (inv.fromPartyId === organizationPartyId);
    const counterPartyId = isInvoiceSale ? inv.toPartyId : inv.fromPartyId;

    // Counterparty names and fiscal id
    const cpParty = ec.entity.find("mantle.party.Organization").condition("partyId", counterPartyId).one()
        || ec.entity.find("mantle.party.Person").condition("partyId", counterPartyId).one();
    const cpName = cpParty ? (cpParty.organizationName || ((cpParty.firstName || '') + ' ' + (cpParty.lastName || ''))) : counterPartyId;

    const cpTaxAuth = ec.entity.find("mantle.other.tax.TaxAuthorityParty").condition("partyId", counterPartyId).list() || [];
    const cpVat = cpTaxAuth[0]?.partyTaxId || '';
    const cpIdent = ec.entity.find("mantle.party.PartyIdentification").condition("partyId", counterPartyId).condition("partyIdTypeEnumId", "PtidSsn").one();
    const cpFiscalCode = cpIdent?.idValue || cpVat;

    const summary = summarizeInvoiceItems(inv);
    const rateLabels = [];
    for (const b of summary.buckets) {
        const label = b.nature ? (b.rate + '% (' + b.nature + ')') : (b.rate + '%');
        rateLabels.push(label);
        const rateKey = (Math.round(b.rate * 100) / 100) + '_' + (b.nature || '');
        if (!rateSummaryMap[rateKey]) {
            rateSummaryMap[rateKey] = {
                rateDescription: b.nature ? ('VAT ' + b.rate + '% - ' + b.nature) : ('VAT ' + b.rate + '%'),
                taxPercentage: b.rate,
                vatNatureCode: b.nature || '',
                taxableAmount: 0,
                taxAmount: 0,
                deductibleAmount: 0,
                nonDeductibleAmount: 0
            };
        }
        rateSummaryMap[rateKey].taxableAmount += b.taxable;
        rateSummaryMap[rateKey].taxAmount += b.tax;
        rateSummaryMap[rateKey].deductibleAmount += (b.tax - b.nonDed);
        rateSummaryMap[rateKey].nonDeductibleAmount += b.nonDed;
    }

    sumTaxable += summary.docTaxable;
    sumTax += summary.docTax;
    sumDocTotal += summary.docTotal;
    sumDeductible += summary.docDeductible;
    sumNonDeductible += summary.docNonDeductible;

    docRows.push({
        invoiceId: inv.invoiceId,
        isSale: isInvoiceSale,
        vatProtocolNum: inv.vatProtocolNum || protocolSeq,
        vatProtocolDate: inv.vatProtocolDate || inv.invoiceDate,
        documentNum: inv.referenceNum || inv.invoiceId,
        documentDate: inv.invoiceDate,
        counterPartyId: counterPartyId,
        counterPartyName: cpName,
        counterPartyTaxId: cpVat || cpFiscalCode || '—',
        taxableAmount: summary.docTaxable,
        taxRateText: rateLabels.length > 0 ? rateLabels.join(', ') : '0%',
        taxAmount: summary.docTax,
        deductibleAmount: summary.docDeductible,
        nonDeductibleAmount: summary.docNonDeductible,
        totalAmount: summary.docTotal
    });
    protocolSeq++;
}

// Page splits for printing
const maxLines = Number(linesPerPage) || 20;
const pages = [];
let curPage = null;
let pageNumber = Number(pageStartingNumber) || 1;
let runningTaxable = 0;
let runningTax = 0;
let runningTotal = 0;

function newPage() {
    curPage = {
        pageNumber: pageNumber,
        pageLabel: fiscalYear + ' / ' + pageNumber,
        broughtForwardTaxable: runningTaxable,
        broughtForwardTax: runningTax,
        broughtForwardTotal: runningTotal,
        carriedForwardTaxable: runningTaxable,
        carriedForwardTax: runningTax,
        carriedForwardTotal: runningTotal,
        documents: []
    };
    pages.push(curPage);
    pageNumber++;
}

if (docRows.length > 0) newPage();

for (let i = 0; i < docRows.length; i++) {
    if (curPage.documents.length >= maxLines) {
        curPage.carriedForwardTaxable = runningTaxable;
        curPage.carriedForwardTax = runningTax;
        curPage.carriedForwardTotal = runningTotal;
        newPage();
    }
    const row = docRows[i];
    runningTaxable += row.taxableAmount;
    runningTax += row.taxAmount;
    runningTotal += row.totalAmount;
    curPage.documents.push(row);
}

if (curPage) {
    curPage.carriedForwardTaxable = runningTaxable;
    curPage.carriedForwardTax = runningTax;
    curPage.carriedForwardTotal = runningTotal;
}

context.pages = pages;
context.vatRateSummaries = Object.values(rateSummaryMap);
context.totalTaxable = sumTaxable;
context.totalTax = sumTax;
context.totalDeductible = sumDeductible;
context.totalNonDeductible = sumNonDeductible;
context.totalInvoiceAmount = sumDocTotal;
context.totalDocuments = docRows.length;
context.salesTaxTotal = salesTaxSum;
context.purchaseTaxDeductibleTotal = purchaseTaxDeductibleSum;
context.salesTaxableTotal = salesTaxableSum;
context.purchaseTaxableTotal = purchaseTaxableSum;
context.netVatDue = salesTaxSum - purchaseTaxDeductibleSum;
context.startPageNumber = Number(pageStartingNumber) || 1;
context.endPageNumber = pageNumber - 1;

const toNum = (v) => (v == null ? 0 : (typeof v === 'object' && typeof v.toNumber === 'function' ? v.toNumber() : (Number(v) || 0)));
const round2 = (v) => Math.round(toNum(v) * 100) / 100;
const outVat = round2(vatData.salesTaxTotal);
const inVat = round2(vatData.purchaseTaxDeductibleTotal);
const prevCred = round2(previousCreditAmount);
const advPay = round2(advancePaymentAmount);
const net = round2(outVat - inVat - prevCred - advPay);

context.outputVat = toDecimal(outVat).setScale(2, 'HALF_UP');
context.inputDeductibleVat = toDecimal(inVat).setScale(2, 'HALF_UP');
context.netVat = toDecimal(net).setScale(2, 'HALF_UP');

if (outVat === 0 && inVat === 0 && net === 0) {
    ec.message.addError("No VAT movements found for the selected period.");
    return;
}

const acctgPref = ec.entity.find("mantle.ledger.config.PartyAcctgPreference")
    .condition("organizationPartyId", organizationPartyId).useCache(true).one();
const currencyUomId = acctgPref?.baseCurrencyUomId || 'EUR';
const txDate = settlementDate || vatData.thruDate || ec.user.nowTimestamp;
const desc = "Periodic VAT Settlement - " + (vatData.periodDescription || vatData.fiscalYear || '');

const txOut = ec.service.sync().name("mantle.ledger.LedgerServices.create#AcctgTrans").parameters({
    acctgTransTypeEnumId: "AttTaxInvoice",
    organizationPartyId: organizationPartyId,
    transactionDate: txDate,
    amountUomId: currencyUomId,
    description: desc
}).call();
const txId = txOut.acctgTransId;
context.acctgTransId = txId;

if (outVat > 0) {
    ec.service.sync().name("mantle.ledger.LedgerServices.create#AcctgTransEntry").parameters({
        acctgTransId: txId, debitCreditFlag: "D",
        amount: toDecimal(outVat).setScale(2, 'HALF_UP'),
        glAccountId: "224000000", description: "Output VAT settlement"
    }).call();
} else if (outVat < 0) {
    ec.service.sync().name("mantle.ledger.LedgerServices.create#AcctgTransEntry").parameters({
        acctgTransId: txId, debitCreditFlag: "C",
        amount: toDecimal(Math.abs(outVat)).setScale(2, 'HALF_UP'),
        glAccountId: "224000000", description: "Output VAT credit adjustment"
    }).call();
}

if (inVat > 0) {
    ec.service.sync().name("mantle.ledger.LedgerServices.create#AcctgTransEntry").parameters({
        acctgTransId: txId, debitCreditFlag: "C",
        amount: toDecimal(inVat).setScale(2, 'HALF_UP'),
        glAccountId: "144000000", description: "Input VAT deductible settlement"
    }).call();
} else if (inVat < 0) {
    ec.service.sync().name("mantle.ledger.LedgerServices.create#AcctgTransEntry").parameters({
        acctgTransId: txId, debitCreditFlag: "D",
        amount: toDecimal(Math.abs(inVat)).setScale(2, 'HALF_UP'),
        glAccountId: "144000000", description: "Input VAT credit adjustment"
    }).call();
}

if (prevCred > 0) {
    ec.service.sync().name("mantle.ledger.LedgerServices.create#AcctgTransEntry").parameters({
        acctgTransId: txId, debitCreditFlag: "C",
        amount: toDecimal(prevCred).setScale(2, 'HALF_UP'),
        glAccountId: "212300000", description: "Previous period VAT credit"
    }).call();
}
if (advPay > 0) {
    ec.service.sync().name("mantle.ledger.LedgerServices.create#AcctgTransEntry").parameters({
        acctgTransId: txId, debitCreditFlag: "C",
        amount: toDecimal(advPay).setScale(2, 'HALF_UP'),
        glAccountId: "212300000", description: "VAT advance payment"
    }).call();
}

if (net > 0) {
    ec.service.sync().name("mantle.ledger.LedgerServices.create#AcctgTransEntry").parameters({
        acctgTransId: txId, debitCreditFlag: "C",
        amount: toDecimal(net).setScale(2, 'HALF_UP'),
        glAccountId: "212300000", description: "Net VAT payable"
    }).call();
} else if (net < 0) {
    ec.service.sync().name("mantle.ledger.LedgerServices.create#AcctgTransEntry").parameters({
        acctgTransId: txId, debitCreditFlag: "D",
        amount: toDecimal(Math.abs(net)).setScale(2, 'HALF_UP'),
        glAccountId: "212300000", description: "Net VAT credit carried forward"
    }).call();
}

ec.service.sync().name("mantle.ledger.LedgerServices.post#AcctgTrans").parameters({
    acctgTransId: txId
}).call();

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmtDec = (n) => (Number(n) || 0).toFixed(2).replace('.', ',');
const org = vatData.organization || {};
const year = String(vatData.fiscalYear || new Date().getFullYear());
const vatId = (org.vatId || '00000000000').replace(/^IT/i, '');
const fiscalCode = org.fiscalCode || vatId;

const toNum = (v) => (v == null ? 0 : (typeof v === 'object' && typeof v.toNumber === 'function' ? v.toNumber() : (Number(v) || 0)));
const vp2 = toNum(vatData.salesTaxableTotal);
const vp3 = toNum(vatData.purchaseTaxableTotal);
const vp4 = toNum(vatData.salesTaxTotal);
const vp5 = toNum(vatData.purchaseTaxDeductibleTotal);
const vp6Diff = vp4 - vp5;
const prevCred = toNum(previousCreditAmount);
const advPay = toNum(advancePaymentAmount);
const vp14Diff = vp6Diff - prevCred - advPay;

let xml = '<?xml version="1.0" encoding="UTF-8"?>\n';
xml += '<iv:Fornitura xmlns:iv="urn:www.agenziaentrate.gov.it:specificheTecniche:sco:ivp" xmlns:ds="http://www.w3.org/2000/09/xmldsig#">\n';
xml += '  <iv:Intestazione>\n';
xml += '    <iv:CodiceFornitura>IVP18</iv:CodiceFornitura>\n';
xml += '    <iv:CodiceFiscaleDichiarante>' + esc(fiscalCode) + '</iv:CodiceFiscaleDichiarante>\n';
xml += '  </iv:Intestazione>\n';
xml += '  <iv:Comunicazione identificativo="00001">\n';
xml += '    <iv:Frontespizio>\n';
xml += '      <iv:CodiceFiscale>' + esc(fiscalCode) + '</iv:CodiceFiscale>\n';
xml += '      <iv:AnnoImposta>' + esc(year) + '</iv:AnnoImposta>\n';
xml += '      <iv:PartitaIVA>' + esc(vatId) + '</iv:PartitaIVA>\n';
xml += '    </iv:Frontespizio>\n';
xml += '    <iv:DatiContabili>\n';
xml += '      <iv:Modulo>\n';
xml += '        <iv:NumeroModulo>1</iv:NumeroModulo>\n';
if (month) {
    xml += '        <iv:Mese>' + Number(month) + '</iv:Mese>\n';
} else {
    xml += '        <iv:Trimestre>' + (Number(quarter) || 1) + '</iv:Trimestre>\n';
}
xml += '        <iv:TotaleOperazioniAttive>' + fmtDec(vp2) + '</iv:TotaleOperazioniAttive>\n';
xml += '        <iv:TotaleOperazioniPassive>' + fmtDec(vp3) + '</iv:TotaleOperazioniPassive>\n';
xml += '        <iv:IvaEsigibile>' + fmtDec(vp4) + '</iv:IvaEsigibile>\n';
xml += '        <iv:IvaDetratta>' + fmtDec(vp5) + '</iv:IvaDetratta>\n';
if (vp6Diff >= 0) {
    xml += '        <iv:IvaDovuta>' + fmtDec(vp6Diff) + '</iv:IvaDovuta>\n';
} else {
    xml += '        <iv:IvaCredito>' + fmtDec(Math.abs(vp6Diff)) + '</iv:IvaCredito>\n';
}
if (prevCred > 0) {
    xml += '        <iv:CreditoPeriodoPrecedente>' + fmtDec(prevCred) + '</iv:CreditoPeriodoPrecedente>\n';
}
if (advPay > 0) {
    xml += '        <iv:Acconto>' + fmtDec(advPay) + '</iv:Acconto>\n';
}
if (vp14Diff >= 0) {
    xml += '        <iv:ImportoDaVersare>' + fmtDec(vp14Diff) + '</iv:ImportoDaVersare>\n';
} else {
    xml += '        <iv:ImportoACredito>' + fmtDec(Math.abs(vp14Diff)) + '</iv:ImportoACredito>\n';
}
xml += '      </iv:Modulo>\n';
xml += '    </iv:DatiContabili>\n';
xml += '  </iv:Comunicazione>\n';
xml += '</iv:Fornitura>\n';

context.xmlText = xml;
context.filename = 'IT' + vatId + '_LIPE_' + year + '_Q' + (Number(quarter) || 1) + '.xml';

const conds = ec.entity.conditionFactory;
const invFind = ec.entity.find('mantle.account.invoice.Invoice')
    .condition('toPartyId', 'equals', organizationPartyId)
    .condition('invoiceDate', 'greater-equals', fromDate)
    .condition('invoiceDate', 'less-equals', thruDate);
const invList = invFind.list() || [];

let totalGross = 0;
let totalNonTaxable = 0;
let totalTaxable = 0;
let totalWithheld = 0;
let totalNet = 0;
let invoiceCount = 0;
const beneficiaryMap = {};

for (const inv of invList) {
    const itemsFind = ec.entity.find('mantle.account.invoice.InvoiceItem')
        .condition('invoiceId', 'equals', inv.invoiceId);
    const items = itemsFind.list() || [];

    let invWithholding = 0;
    let invTaxable = 0;
    let invNonTaxable = 0;
    let hasWithholding = false;
    let reason = 'A';
    let taxCode = '1040';

    for (const it of items) {
        const amt = (Number(it.quantity) || 1) * (Number(it.amount) || 0);
        if (it.withholdingTaxTypeEnumId || it.itemTypeEnumId === 'ItemTaxWithholding') {
            hasWithholding = true;
            const rate = Number(it.withholdingTaxRate) || 20.0;
            const withheld = (amt * rate / 100);
            invWithholding += withheld;
            invTaxable += amt;
            if (it.withholdingPaymentReason) reason = it.withholdingPaymentReason;
            if (it.withholdingTaxTypeEnumId === 'RT04') taxCode = '1038';
        } else if (it.taxPercentage === 0) {
            invNonTaxable += amt;
        } else {
            // Standard service item
            if (inv.invoiceTypeEnumId === 'InvoiceCommission' || inv.description?.toLowerCase().includes('parcella')) {
                hasWithholding = true;
                invTaxable += amt;
                invWithholding += (amt * 0.20);
            }
        }
    }

    if (hasWithholding || inv.invoiceTypeEnumId === 'InvoiceCommission') {
        invoiceCount++;
        const partyId = inv.fromPartyId;
        let b = beneficiaryMap[partyId];
        if (!b) {
            // Find party info
            const pFind = ec.entity.find('mantle.party.PartyDetail').condition('partyId', 'equals', partyId);
            const pDetail = pFind.one();
            const idents = ec.entity.find('mantle.party.PartyIdentification').condition('partyId', 'equals', partyId).list() || [];
            const cf = idents.find(i => i.partyIdTypeEnumId === 'PtidSsn')?.idValue || '';
            const vatFind = ec.entity.find('mantle.other.tax.TaxAuthorityParty').condition('partyId', 'equals', partyId).list() || [];
            const piva = vatFind?.[0]?.partyTaxId || '';

            b = {
                partyId: partyId,
                beneficiaryName: pDetail?.organizationName || (pDetail?.firstName ? (pDetail.firstName + ' ' + pDetail.lastName) : partyId),
                fiscalCode: cf,
                vatNumber: piva,
                paymentReason: reason,
                f24TaxCode: taxCode,
                grossAmount: 0,
                nonTaxableAmount: 0,
                taxableAmount: 0,
                withheldAmount: 0,
                netAmount: 0,
                invoices: []
            };
            beneficiaryMap[partyId] = b;
        }

        const gross = invTaxable + invNonTaxable;
        const net = gross - invWithholding;
        b.grossAmount += gross;
        b.nonTaxableAmount += invNonTaxable;
        b.taxableAmount += invTaxable;
        b.withheldAmount += invWithholding;
        b.netAmount += net;
        b.invoices.push({
            invoiceId: inv.invoiceId,
            invoiceNumber: inv.referenceNumber || inv.invoiceId,
            invoiceDate: inv.invoiceDate,
            paidDate: inv.paidDate || inv.dueDate,
            grossAmount: gross,
            taxableAmount: invTaxable,
            withheldAmount: invWithholding,
            netAmount: net
        });

        totalGross += gross;
        totalNonTaxable += invNonTaxable;
        totalTaxable += invTaxable;
        totalWithheld += invWithholding;
        totalNet += net;
    }
}

context.fiscalYear = fiscalYear;
context.beneficiaries = Object.values(beneficiaryMap);
context.totalGrossAmount = totalGross;
context.totalNonTaxableAmount = totalNonTaxable;
context.totalTaxableAmount = totalTaxable;
context.totalWithheldAmount = totalWithheld;
context.totalNetAmount = totalNet;
context.totalInvoicesCount = invoiceCount;
